head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[p > M > openPopup]<br/>지정한 옵션에 맞게 팝업을 생성하여 엽니다.",
    "validation" : [
        "options.dataObject.data(선택) 파라미터로 options.dataObject.type 속성에 설정한 데이터 종류에 맞게 전달할 데이터를 설정합니다.",
        "options.dataObject.data(선택) 파라미터 생략 시, 기본값 undefined 로 동작합니다.",
        "options.dataObject.name(선택) 파라미터로 팝업에서 전달된 데이터에 접근할 때 사용할 이름을 설정합니다.",
        "$p.getParameter() 메소드를 사용하여 팝업에서 전달된 데이터에 접근할 수 있으면 여기에 설정된 값을 파라미터로 설정합니다.",
        "options.dataObject.name(선택) 파라미터 생략 시, 기본값 undefined 로 동작합니다.",
    ]
}



scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();

    $c.gcm.createLabel('label="[전제] 팝업 화면은 $p.getParameter 에 이름 paramData 를 넘겨 받은 값을 표시합니다.\n[참고] data 설정 시 전달 데이터 : xml = employee XML 문서, string = 홍길동, json = name/dept 객체, array = 이름 3건"', '', 'label1');

    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



scwin.popupUrl = "/sample/common_link/p_openPopup_popup.xml";



scwin.out = function (str) {
    wf_body_bottom.getObj("scwin").setReturnValue(str);
};



// 이전 테스트 팝업 정리 (내부 팝업을 정리했으면 true 반환)
scwin.closeAllPopup = function () {
    let list = $p.getAllPopupList().slice();
    let closedInner = false;
    for (let i = 0; i < list.length; i++) {
        let pw = list[i].popupWin;
        try {
            if (pw && typeof pw.forceClose === "function") {
                pw.forceClose();
                closedInner = true;
            } else if (pw && typeof pw.close === "function") {
                pw.close();
            }
        } catch (e) {}
    }
    return closedInner;
};



// 이전 팝업 정리 후 openPopup 실행
// (내부 팝업 정리는 비동기로 끝나므로 300ms 후 연다. 클릭 직후 5초 이내라 browserPopup 도 사용자 동작으로 처리됨)
scwin.runOpenPopup = function (optionList, callback) {
    let fn = function () {
        for (let i = 0; i < optionList.length; i++) {
            $p.openPopup(scwin.popupUrl, optionList[i]);
        }
        if (callback) callback();
    };
    if (scwin.closeAllPopup()) {
        setTimeout(fn, 300);
    } else {
        fn();
    }
};



// options.id 로 팝업 정보 조회 (Page Scope 적용 시 실행 ID 는 'mf_' 접두사가 붙음)
scwin.findPopup = function (id) {
    let list = $p.getAllPopupList();
    for (let i = list.length - 1; i >= 0; i--) {
        if ((list[i].options.org_id === id || list[i].options.id === id) && list[i].popupWin) return list[i];
    }
    return null;
};



// options.id 로 팝업 최상위 div 조회
scwin.popupEl = function (id) {
    return document.querySelector(".w2popup_window[id$='" + id + "']");
};



// 팝업 내부 요소(타이틀바 버튼 등) 조회
scwin.popupPart = function (id, suffix) {
    let el = scwin.popupEl(id);
    return el ? document.getElementById(el.id + "_" + suffix) : null;
};



scwin.rectStr = function (el) {
    let r = el.getBoundingClientRect();
    return "left " + Math.round(r.left + window.scrollX) + ", top " + Math.round(r.top + window.scrollY) + " / 크기 : " + Math.round(r.width) + " x " + Math.round(r.height);
};

scwin.btn_openPopup_onclick = function () {
    let type = par_type.getValue();
    let dataType = par_dataType.getValue();
    let data = par_data.getValue();
    let name = par_name.getValue();

    let options = { id: "popup_1", type: type, width: "560px", height: "320px", popupName: "dataObject 팝업" };
    let dataObject = { type: dataType };
    if (data === "set") {
        if (dataType === "xml") {
            dataObject.data = WebSquare.xml.parse("<employee><name>홍길동</name><dept>개발팀</dept></employee>");
        } else if (dataType === "string") {
            dataObject.data = "홍길동";
        } else if (dataType === "array") {
            dataObject.data = ["홍길동", "김철수", "이영희"];
        } else {
            dataObject.data = { name: "홍길동", dept: "개발팀" };
        }
    }
    if (name !== "") dataObject.name = name;
    options.dataObject = dataObject;

    scwin.runOpenPopup([options], scwin.printResult);
};



// validation 1~5 판정 출력 (팝업 화면이 $p.getParameter('paramData') 로 받은 값)
// 팝업 화면이 값을 표시하면 바로 출력하고, 5초가 지나도 표시가 없으면 그 시점 상태를 출력
scwin.printResult = function () {
    let start = Date.now();
    let check = function () {
        let pw = scwin.findPopup("popup_1");
        let txt = "";
        if (pw) {
            try {
                let doc = (pw.options.type === "browser") ? pw.popupWin.document : document;
                let el = doc.querySelector("[id$='tbx_param']");
                txt = el ? el.textContent : "";
            } catch (e) {}
        }
        if (txt === "" && Date.now() - start < 5000) {
            setTimeout(check, 100);
            return;
        }
        scwin.out(pw ? "팝업 수신 " + txt : "팝업 생성 : false");
    };
    check();
};
